def is_sorted(lst):
    if len(lst) <= 1:
        return True
    count = 1
    for i in range(1, len(lst)):
        if lst[i] < lst[i-1]:
            return False
        if lst[i] == lst[i-1]:
            count += 1
            if count > 2:
                return False
        else:
            count = 1
    return True
